const PORT = process.env.PORT || 3004;

const headers = {
  "Content-Type": "application/json",
  "Access-Control-Allow-Headers": "*",
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "OPTIONS,GET,POST",
};

const serverUnixTime = () => Math.floor(Date.now() / 1000);

const buildJsonResponse = (
  statusCode,
  { isSuccess, responseMsg, data = {} }
) => ({
  statusCode,
  body: JSON.stringify({
    isSuccess,
    responseMsg,
    data,
    serverDateTime: serverUnixTime(),
  }),
  headers,
});

const handleGLUnderWriting = async (
  accountId,
  ratingPeriodId,
  generalLiabilityId
) => {
  const data = sampleGLUnderwriting.filter((item) => {
    const matchesAccount =
      Number.isNaN(accountId) || item.AccountID === accountId;
    const matchesRating =
      Number.isNaN(ratingPeriodId) || item.RatingPeriodID === ratingPeriodId;
    const matchesGl =
      generalLiabilityId === null ||
      item.GeneralLiabilityId === String(generalLiabilityId);
    return matchesAccount && matchesRating && matchesGl;
  });

  return buildJsonResponse(200, {
    isSuccess: true,
    responseMsg: "GL Under Writing loaded successfully",
    data,
  });
};

export const handlerGLUnderWriting = async (event) => {
  const method = (event.httpMethod || "").toUpperCase();
  const path = event.path || "";
  const accountId = Number(event.query?.accountId);
  const ratingPeriodId = Number(event.query?.ratingPeriodId);
  const generalLiabilityId = event.query?.generalLiabilityId
    ? Number(event.query.generalLiabilityId)
    : null;
  if (method === "OPTIONS") {
    return {
      statusCode: 204,
      body: "",
      headers,
    };
  }

  try {
    if (path === "/gl/under_writing" && method === "GET") {
      return await handleGLUnderWriting(accountId, ratingPeriodId, generalLiabilityId);
    }

    return buildJsonResponse(404, {
      isSuccess: false,
      responseMsg: "Route not found",
      data: {},
    });
  } catch (error) {
    console.error(error);

    return buildJsonResponse(500, {
      isSuccess: false,
      responseMsg: error.message,
      data: {},
    });
  }
};


const server = http.createServer(async (req, res) => {
  let body = "";

  req.on("data", (chunk) => {
    body += chunk;
  });

  req.on("end", async () => {
    const url = new URL(req.url, `http://${req.headers.host}`);
    const event = {
      httpMethod: req.method,
      path: url.pathname,
      query: Object.fromEntries(url.searchParams),
      body,
    };

    const response = await handlerGLUnderWriting(event);

    res.writeHead(response.statusCode, response.headers);
    res.end(response.body);
  });
});

const start = async () => {
  try {
    server.listen(PORT, () => {
      console.log(
        `Server running on http://localhost:${PORT}`
      );

      console.log(
        `Test URL: http://localhost:${PORT}/gl/under_writing`
      );
    });
  } catch (error) {
    console.error(
      "Failed to start application:",
      error.message
    );
    process.exit(1);
  }
};

const shutdown = async () => {
  try {
    console.log("Application shutdown completed");
  } catch (err) {
    console.error(err);
  }
};

process.on("SIGINT", async () => {
  await shutdown();
  process.exit(0);
});

process.on("SIGTERM", async () => {
  await shutdown();
  process.exit(0);
});

process.on("exit", shutdown);

start();
